nterAfterRestore(){updateStepsCount();if(status!=null)status.setText(tr("Step counter: finished","وضعیت قدم‌شمار: پایان‌یافته"));}void updateStepsCount(){TextView count=findViewById(R.id.stepsCountText);if(count!=null){String day=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new java.util.Date());int n=getSharedPreferences("step_counter",MODE_PRIVATE).getInt("steps_"+day,0);int goal=getSharedPreferences("fityar_preferences",MODE_PRIVATE).getInt("step_goal",5000);count.setText(tr("Today’s steps\n","قدم‌های امروز\n")+String.format(Locale.US,"%,d",n)+tr(" of "," از ")+String.format(Locale.US,"%,d",goal)+tr(" steps"," قدم"));ProgressBar progress=findViewById(R.id.stepProgressBar);if(progress!=null)progress.setProgress((int)Math.min(100L,100L*n/Math.max(1,goal)));}}

 interface TimeCallback { void selected(long millis); }
 void chooseDateTime(long initial,TimeCallback callback){Calendar cal=Calendar.getInstance();cal.setTimeInMillis(initial);if(!english()){String jalali=JalaliDate.fromGregorian(cal.get(Calendar.YEAR),cal.get(Calendar.MONTH)+1,cal.get(Calendar.DAY_OF_MONTH));PersianDatePicker.show(this,jalali,selected->{long date=jalaliToMillis(selected,initial);Calendar chosen=Calendar.getInstance();chosen.setTimeInMillis(date);new TimePickerDialog(this,(tp,h,mi)->{chosen.set(Calendar.HOUR_OF_DAY,h);chosen.set(Calendar.MINUTE,mi);chosen.set(Calendar.SECOND,0);callback.selected(chosen.getTimeInMillis());},cal.get(Calendar.HOUR_OF_DAY),cal.get(Calendar.MINUTE),true).show();});return;}new DatePickerDialog(this,(dp,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.setTimeInMillis(initial);chosen.set(Calendar.YEAR,y);chosen.set(Calendar.MONTH,m);chosen.set(Calendar.DAY_OF_MONTH,d);new TimePickerDialog(this,(tp,h,mi)->{chosen.set(Calendar.HOUR_OF_DAY,h);chosen.set(Calendar.MINUTE,mi);chosen.set(Calendar.SECOND,0);callback.selected(chosen.getTimeInMillis());},chosen.get(Calendar.HOUR_OF_DAY),chosen.get(Calendar.MINUTE),true).show();},cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();}
 long jalaliToMillis(String date,long initial){String[] p=date.split("/");int jy=Integer.parseInt(p[0]),jm=Integer.parseInt(p[1]),jd=Integer.parseInt(p[2]);Calendar c=Calendar.getInstance();c.setTimeInMillis(initial);int gy=jy+621;for(int y=gy-1;y<=gy+1;y++)for(int m=0;m<12;m++)for(int d=1;d<=31;d++){c.set(y,m,d,12,0,0);c.set(Calendar.MILLISECOND,0);if(c.get(Calendar.YEAR)==y&&c.get(Calendar.MONTH)==m&&c.get(Calendar.DAY_OF_MONTH)==d&&JalaliDate.fromGregorian(y,m+1,d).equals(String.format(java.util.Locale.US,"%04d/%02d/%02d",jy,jm,jd)))return c.getTimeInMillis();}throw new IllegalArgumentException("Invalid Jalali date");}
 String stamp(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);String time=new java.text.SimpleDateFormat("HH:mm",java.util.Locale.US).format(new java.util.Date(millis));return english()?new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new java.util.Date(millis))+" "+time:JalaliDate.fromGregorian(c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH))+" "+time;}
 void sleepEntry(){Calendar cal=Calendar.getInstance();long end=cal.getTimeInMillis();cal.add(Calendar.HOUR_OF_DAY,-8);final long[] start={cal.getTimeInMillis()},finish={end};LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(24,12,24,12);TextView s=new TextView(this),e=new TextView(this),note=new TextView(this);Runnable labels=()->{s.setText(tr("Sleep start: ","شروع خواب: ")+stamp(start[0])+"  ✎");e.setText(tr("Wake up: ","زمان بیداری: ")+stamp(finish[0])+"  ✎");};labels.run();note.setText(tr("Select the sleep and wake-up date/time.","تاریخ و ساعت خوابیدن و بیدارشدن را انتخاب کنید."));s.setPadding(0,16,0,16);e.setPadding(0,16,0,16);s.setOnClickListener(v->chooseDateTime(start[0],t->{start[0]=t;labels.run();}));e.setOnClickListener(v->chooseDateTime(finish[0],t->{finish[0]=t;labels.run();}));box.addView(s);box.addView(e);box.addView(note);new AlertDialog.Builder(this).setTitle(tr("Sleep log","ثبت خواب")).setView(box).setPositiveButton(tr("Save","ذخیره"),(d,w)->{try{db.addSleep(start[0],finish[0]);long mins=(finish[0]-start[0])/60000;msg(tr("Saved","ذخیره شد"),tr("Sleep duration: ","مدت خواب: ")+(mins/60)+tr(" h "," ساعت ")+(mins%60)+tr(" min"," دقیقه"));}catch(Exception ex){msg(tr("Invalid time","زمان نامعتبر"),tr("Wake-up time must be after sleep start.","زمان بیداری باید بعد از شروع خواب باشد."));}}).setNegativeButton(tr("Cancel","لغو"),null).show();}
 void vitalsEntry(){final long[] at={System.currentTimeMillis()};LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(24,12,24,12);TextView dt=new TextView(this);Runnable label=()->dt.setText(tr("Date and time: ","تاریخ و ساعت: ")+stamp(at[0])+"  ✎");label.run();dt.setPadding(0,12,0,12);dt.setOnClickListener(v->chooseDateTime(at[0],t->{at[0]=t;label.run();}));EditText sys=edit(tr("Upper pressure (systolic), e.g. 120","فشار بالا (سیستول)، مثلاً ۱۲۰"),"120"),dia=edit(tr("Lower pressure (diastolic), e.g. 80","فشار پایین (دیاستول)، مثلاً ۸۰"),"80"),pulse=edit(tr("Heart rate (beats/min)","ضربان قلب (در دقیقه)"),"70");sys.setInputType(2);dia.setInputType(2);pulse.setInputType(2);box.addView(dt);TextView sysLabel=new TextView(this);sysLabel.setText(tr("Systolic / upper pressure (mmHg)","فشار خون بالا (سیستول) ـ میلی‌متر جیوه"));box.addView(sysLabel);box.addView(sys);TextView diaLabel=new TextView(this);diaLabel.setText(tr("Diastolic / lower pressure (mmHg)","فشار خون پایین (دیاستول) ـ میلی‌متر جیوه"));box.addView(diaLabel);box.addView(dia);TextView pulseLabel=new TextView(this);pulseLabel.setText(tr("Heart rate (beats per minute)","ضربان قلب (تعداد در دقیقه)"));box.addView(pulseLabel);box.addView(pulse);new AlertDialog.Builder(this).setTitle(tr("Blood pressure and heart rate","فشار خون و ضربان قلب")).setView(box).setPositiveButton(tr("Save","ذخیره"),(d,w)->{try{db.addVitals(at[0],Integer.parseInt(sys.getText().toString()),Integer.parseInt(dia.getText().toString()),Integer.parseInt(pulse.getText().toString()));msg(tr("Saved","ذخیره شد"),tr("Measurement saved.","اندازه‌گیری ذخیره شد."));}catch(Exception ex){msg(tr("Invalid values","مقادیر نامعتبر"),tr("Enter valid pressure and pulse values.","مقادیر معتبر فشار و ضربان را وارد کنید."));}}).setNegativeButton(tr("Cancel","لغو"),null).show();}
