   stats.setText(english()?"Logged workouts: "+workouts+"\nTotal sets: "+totalSets+"   •   Reps: "+totalReps+"\nSteps in range: "+String.format(java.util.Locale.US,"%,d",stepsInRange)+"\nTraining volume: "+String.format(java.util.Locale.US,"%.1f",volume)+" kg×reps":"جلسه‌های ثبت‌شده: "+workouts+"\nمجموع ست‌ها: "+totalSets+"   •   تکرارها: "+totalReps+"\nقدم‌های ثبت‌شده در این بازه: "+String.format(java.util.Locale.US,"%,d",stepsInRange)+"\nحجم تمرین وزنه‌ای: "+String.format(java.util.Locale.US,"%.1f",volume)+" کیلوگرم×تکرار");
