   else {for(String key:counts.keySet()){String label=key.length()>=5?key.substring(key.length()-5):key;if(english()){try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US);java.util.Date d=f.parse(key);label=new java.text.SimpleDateFormat("MM-dd",java.util.Locale.US).format(d);}catch(Exception ignored){}}labels.add(label);vals.add((float)counts.get(key));}}
